using System;
using System.IO;
using Newtonsoft.Json.Linq;

public class CPHInline
{
    public bool Execute()
    {
        string executorName = args["userName"].ToString();
        bool isModerator = bool.Parse(args["isModerator"].ToString());
        bool isBroadcaster = bool.Parse(args["isBroadcaster"].ToString());

        // Check permissions
        if (!isModerator && !isBroadcaster) {
            CPH.SendMessage($"@{executorName}, this command is only available to moderators.");
            return false;
        }

        string inputText = args["rawInput"].ToString();

        // Parse input: !resetuser @username
        if (string.IsNullOrEmpty(inputText)) {
            CPH.SendMessage($"@{executorName}, usage: !resetuser @username. Example: !resetuser @user");
            return false;
        }

        string targetUser = inputText.Trim().TrimStart('@');

        // Get target user ID
        var userInfo = CPH.TwitchGetUser(targetUser);
        if (userInfo == null) {
            CPH.SendMessage($"@{executorName}, user @{targetUser} not found.");
            return false;
        }

        string targetUserId = userInfo.UserId;
        string targetUserName = userInfo.UserLogin;

        // Load user data
        string dataPath = @"C:\StreamerBot\UserData\eggs.json";

        if (!File.Exists(dataPath)) {
            CPH.SendMessage($"@{executorName}, no egg data found.");
            return false;
        }

        string jsonData = File.ReadAllText(dataPath);
        JObject data = JObject.Parse(jsonData);

        // Check if user exists
        if (data["users"] == null || data["users"][targetUserId] == null) {
            CPH.SendMessage($"@{executorName}, @{targetUserName} has no egg data to reset.");
            return false;
        }

        // Reset user data
        data["users"][targetUserId] = new JObject();
        data["users"][targetUserId]["eggs"] = 0;
        data["users"][targetUserId]["d20Tokens"] = 0;
        data["users"][targetUserId]["rrTokens"] = 0;
        data["users"][targetUserId]["adventureState"] = "";
        data["users"][targetUserId]["lastAdventure"] = "";
        data["users"][targetUserId]["totalAdventures"] = 0;

        File.WriteAllText(dataPath, data.ToString());

        CPH.SendMessage($"🔄 @{targetUserName}'s economy data has been reset by @{executorName}.");

        return true;
    }
}
